import React from 'react';
import { SafeAreaView, StyleSheet, Alert } from 'react-native';
import { WebView } from 'react-native-webview';
import * as Print from 'expo-print';

const APP_HTML = "<!doctype html>\n<html lang=\"ar\" dir=\"rtl\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>مؤسسة مدد العاصمة - إدارة النقل</title>\n<style>\n*{box-sizing:border-box}\nbody{margin:0;background:#f5f7fa;font-family:Tahoma,Arial,sans-serif;color:#172033}\nheader{background:#0f766e;color:white;padding:18px;text-align:center;position:sticky;top:0;z-index:5}\nheader h1{margin:0;font-size:21px}\nmain{max-width:980px;margin:auto;padding:14px}\n.tabs{display:grid;grid-template-columns:repeat(2,1fr);gap:8px;margin-bottom:14px;position:sticky;top:76px;z-index:4;background:#f5f7fa;padding:8px 0}\n.tabs button{border:0;border-radius:12px;padding:12px 8px;font-weight:bold;background:white;color:#334155;box-shadow:0 1px 4px #0001;cursor:pointer}\n.tabs button.active{background:#0f766e;color:white}\n.home-section{scroll-margin-top:170px;margin-bottom:16px}\n.home-section>.card:first-child,.home-section.card{border-top:4px solid #0f766e}\n.section-note{margin:-4px 0 12px;color:#64748b;font-size:13px}\n@media(min-width:800px){.tabs{grid-template-columns:repeat(5,1fr)}}\n.card{background:white;border-radius:16px;padding:14px;margin-bottom:12px;box-shadow:0 2px 8px #0001}\nh2{font-size:18px;margin:0 0 12px}\n.grid-buttons{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}\n.bigbtn{border:0;border-radius:16px;background:white;padding:22px 10px;font:700 18px Tahoma;color:#0f766e;box-shadow:0 2px 8px #0002}\n.bigbtn small{display:block;color:#64748b;font-size:12px;margin-top:6px}\n.driver-card{position:relative}\n.driver-card .bigbtn{width:100%;padding-bottom:54px}\n.delete-driver-btn{position:absolute;left:8px;bottom:8px;border:0;border-radius:7px;padding:4px 8px;background:#fee2e2;color:#991b1b;font-size:11px;font-weight:800;line-height:1.2;cursor:pointer;z-index:2}\n.delete-driver-btn:active{transform:scale(.98)}\nlabel{display:block;font-size:12px;color:#64748b;margin:7px 0 5px}\ninput,select{width:100%;padding:11px;border:1px solid #cbd5e1;border-radius:10px;font:inherit}\n.formgrid{display:grid;grid-template-columns:1fr 1fr;gap:9px}\n.full{grid-column:1/-1}\n.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:11px}\n.btn{border:0;border-radius:10px;padding:11px 14px;font-weight:bold;cursor:pointer}\n.primary{background:#0f766e;color:white}\n.gray{background:#e2e8f0;color:#172033}\n.red{background:#fee2e2;color:#991b1b}\n.hidden{display:none!important}\n.scroll{overflow:auto}\ntable{width:100%;border-collapse:collapse;min-width:760px}\nth,td{padding:10px 8px;border-bottom:1px solid #e5e7eb;text-align:right;font-size:13px;vertical-align:middle}\nth{background:#f8fafc}\n.thumb{width:48px;height:62px;object-fit:cover;border-radius:6px;cursor:pointer}\n.empty{text-align:center;color:#64748b;padding:24px}\n.payment-status-print{display:none}\n.payment-status-screen{display:inline}\n.modal{display:none;position:fixed;inset:0;background:#000b;z-index:20;align-items:center;justify-content:center;padding:12px}\n.modal.on{display:flex}\n.modal img{max-width:95vw;max-height:90vh}\n@media(max-width:650px){\n .tabs{top:70px}\n .grid-buttons{grid-template-columns:1fr}\n .formgrid{grid-template-columns:1fr}\n .full{grid-column:auto}\n}\n@media print{\n  body{background:white}\n  header,.tabs,#home,.no-print,.btn,.actions{display:none!important}\n  main{max-width:none;padding:0}\n  #detailPage{display:block!important}\n  .card{box-shadow:none;border:0;padding:0}\n  table{min-width:0;width:100%}\n  th,td{font-size:11px;padding:6px}\n  .thumb{width:35px;height:45px}\n  .payment-status-screen{display:none!important}\n  .payment-status-print{display:inline!important;font-weight:700}\n  /* إخفاء عمود صورة الفاتورة/السند من جميع الكشوف المطبوعة */\n  #tripsTable th:nth-child(8), #tripsTable td:nth-child(8){display:none!important}\n  #printHeader{display:block!important;text-align:center;margin-bottom:14px}\n  body.print-expenses #detailPage > .card:not(#driverExpenses),\n  body.print-expenses #printHeader{display:none!important}\n  body.print-expenses #driverExpenses{display:block!important}\n  body.print-expenses #expensePrintHeader{display:block!important;text-align:center;margin-bottom:14px}\n  body.print-expenses #driverExpenses > .formgrid,\n  body.print-expenses #driverExpenses > .actions{display:none!important}\n  body.print-driver-customers #detailPage{display:none!important}\n  body.print-driver-customers #home,\n  body.print-driver-customers #externalDrivers,\n  body.print-driver-customers #externalDriversTable{display:none!important}\n  body.print-driver-customers #groupedDriverReport{display:block!important}\n  body.print-driver-customers #groupedDriverReport .customer-section{page-break-inside:avoid;margin-bottom:22px}\n  body.print-driver-monthly #detailPage,\n  body.print-driver-monthly #home,\n  body.print-driver-monthly #groupedDriverReport{display:none!important}\n  body.print-driver-monthly #monthlyDriverReport{display:block!important}\n  body.print-driver-monthly #monthlyDriverReport .report-section{page-break-inside:avoid;margin-bottom:22px}\n}\n#groupedDriverReport{display:none}\n#monthlyDriverReport{display:none}\n#monthlyDriverReport .report-summary{display:flex;gap:12px;flex-wrap:wrap;justify-content:center;margin:12px 0 18px}\n#monthlyDriverReport .summary-pill{border:1px solid #cbd5e1;border-radius:10px;padding:8px 12px;font-weight:700}\n#monthlyDriverReport h3{margin:16px 0 8px}\n#groupedDriverReport .report-summary{display:flex;gap:14px;flex-wrap:wrap;justify-content:center;margin:10px 0 18px}\n#groupedDriverReport .summary-pill{border:1px solid #cbd5e1;border-radius:10px;padding:8px 14px;font-weight:700}\n#groupedDriverReport h3{margin:14px 0 8px}\n#printHeader{display:none}\n</style>\n</head>\n<body>\n<header><h1>مؤسسة مدد العاصمة</h1><div style=\"margin-top:5px;font-size:14px;opacity:.9\">إدارة النقل والمشاوير</div></header>\n<main>\n\n<div id=\"home\">\n  <div class=\"card no-print\" style=\"margin-bottom:12px;padding:12px\">\n    <div style=\"display:flex;align-items:end;gap:10px;flex-wrap:wrap\">\n      <div style=\"flex:1;min-width:190px\">\n        <label style=\"font-weight:800\">الشهر الميلادي</label>\n        <input id=\"homeMonth\" type=\"month\" onchange=\"setHomeMonth(this.value)\" style=\"font-size:18px;font-weight:800\">\n      </div>\n      <div id=\"homeMonthName\" class=\"section-note\" style=\"font-weight:800;padding-bottom:10px\"></div>\n    </div>\n  </div>\n  <div class=\"tabs no-print\">\n    <button id=\"tabDrivers\" class=\"active\" onclick=\"showHomeMode('drivers')\">السواقين</button>\n    <button id=\"tabCustomers\" onclick=\"showHomeMode('customers')\">العملاء</button>\n    <button id=\"tabTaxInvoices\" onclick=\"showHomeMode('taxInvoices')\">الفواتير</button>\n    <button id=\"tabAccounts\" onclick=\"showHomeMode('accounts')\">الحسابات</button>\n    <button id=\"tabExternal\" onclick=\"showHomeMode('external')\">السائقون الخارجيون</button>\n  </div>\n\n  <div id=\"driversHome\" class=\"home-section\">\n    <div class=\"card\">\n      <h2>السواقين الأساسيون</h2><div class=\"section-note\">إدارة السائقين ومشاوير كل سائق من نفس الصفحة.</div>\n      <div id=\"driverMonthlyTitle\" class=\"section-note\" style=\"font-weight:700;margin:8px 0\"></div>\n      <div class=\"scroll\"><table><thead><tr><th>السائق</th><th>السيارة / المقطورة</th><th>عدد المشاوير</th><th>الإجمالي</th><th>فتح</th></tr></thead><tbody id=\"driverMonthlyRows\"></tbody></table></div>\n      <div class=\"actions\" style=\"margin:12px 0\">\n        <button class=\"btn primary\" onclick=\"openAllDrivers()\">فتح جدول هذا الشهر لجميع السواقين</button>\n      </div>\n      <h3 style=\"margin:14px 0 8px\">جميع السواقين المسجلين</h3>\n      <div id=\"driverButtons\" class=\"grid-buttons\"></div>\n    </div>\n    <div class=\"card\">\n      <h2>إضافة سواق</h2>\n      <div class=\"formgrid\">\n        <div><label>اسم السواق</label><input id=\"newDriver\"></div>\n        <div><label>رقم السيارة / المقطورة</label><input id=\"newVehicle\"></div>\n      </div>\n      <div class=\"actions\"><button class=\"btn primary\" onclick=\"addDriver()\">إضافة السواق</button></div>\n    </div>\n  </div>\n\n  <div id=\"customersHome\" class=\"home-section\">\n    <div class=\"card\">\n      <h2>العملاء</h2><div class=\"section-note\">عرض العملاء وفتح جدول كل عميل.</div>\n      <div id=\"customerMonthlyTitle\" class=\"section-note\" style=\"font-weight:700;margin:8px 0\"></div>\n      <div class=\"scroll\"><table><thead><tr><th>العميل</th><th>عدد المشاوير</th><th>الإجمالي</th><th>فتح</th></tr></thead><tbody id=\"customerMonthlyRows\"></tbody></table></div>\n      <div class=\"actions\" style=\"margin:12px 0\">\n        <button class=\"btn primary\" onclick=\"openAllCustomers()\">فتح جدول هذا الشهر لجميع العملاء</button>\n      </div>\n      <h3 style=\"margin:14px 0 8px\">جميع العملاء المسجلين</h3>\n      <div id=\"customerButtons\" class=\"grid-buttons\"></div>\n    </div>\n    <div class=\"card\">\n      <h2>إضافة عميل</h2>\n      <div class=\"formgrid\">\n        <div><label>اسم العميل</label><input id=\"newCustomer\"></div>\n      </div>\n      <div class=\"actions\"><button class=\"btn primary\" onclick=\"addCustomer()\">إضافة العميل</button></div>\n    </div>\n  </div>\n\n  <div id=\"taxInvoicesHome\" class=\"home-section\">\n    <div class=\"card\">\n      <h2>الفواتير الضريبية</h2><div class=\"section-note\">حفظ الفاتورة ومتابعة حالة السداد.</div><h2 style=\"font-size:16px\">حفظ فاتورة ضريبية</h2>\n      <div class=\"formgrid\">\n        <div><label>العميل</label><select id=\"taxInvoiceCustomer\"></select></div>\n        <div><label>رقم الفاتورة</label><input id=\"taxInvoiceNumber\" placeholder=\"رقم الفاتورة\"></div>\n        <div><label>تاريخ الفاتورة</label><input id=\"taxInvoiceDate\" type=\"date\"></div>\n        <div><label>إجمالي الفاتورة</label><input id=\"taxInvoiceAmount\" type=\"number\" step=\"0.01\" placeholder=\"0.00\"></div>\n        <div><label>حالة السداد</label><select id=\"taxInvoicePaymentStatus\"><option value=\"unpaid\">باقي - لم يتم السداد</option><option value=\"paid\">تم السداد</option></select></div>\n        <div class=\"full\"><label>صورة أو ملف PDF للفاتورة</label><input id=\"taxInvoiceFile\" type=\"file\" accept=\"image/*,application/pdf\"><small style=\"display:block;color:#64748b;margin-top:5px\">اختر الفاتورة من الاستديو أو ملفات واتساب.</small></div>\n        <div class=\"full\"><label>ملاحظة</label><input id=\"taxInvoiceNote\" placeholder=\"ملاحظة اختيارية\"></div>\n      </div>\n      <div class=\"actions\"><button class=\"btn primary\" onclick=\"addTaxInvoice()\">حفظ الفاتورة الضريبية</button></div>\n    </div>\n\n    <div class=\"card\">\n      <h2>الفواتير الضريبية المحفوظة</h2>\n      <div class=\"scroll\">\n        <table>\n          <thead><tr><th>التاريخ</th><th>العميل</th><th>رقم الفاتورة</th><th>الإجمالي</th><th>حالة السداد</th><th>الملف</th><th>ملاحظة</th><th></th></tr></thead>\n          <tbody id=\"taxInvoiceRows\"></tbody>\n        </table>\n      </div>\n    </div>\n  </div>\n\n  <div id=\"accountsHome\" class=\"home-section\">\n    <div class=\"card\">\n      <h2>الحسابات</h2><div class=\"section-note\">ملخص المستحقات والمبالغ والمصاريف.</div>\n      <div class=\"formgrid\">\n        <div class=\"card\" style=\"margin:0;text-align:center\">\n          <div style=\"color:#64748b\">مستحقات العملاء لك</div>\n          <div id=\"accountsReceivables\" style=\"font-size:28px;font-weight:800;margin-top:6px\">0 ر.س</div>\n        </div>\n        <div class=\"card\" style=\"margin:0;text-align:center\">\n          <div style=\"color:#64748b\">المسدّد من العملاء</div>\n          <div id=\"accountsCollected\" style=\"font-size:28px;font-weight:800;margin-top:6px\">0 ر.س</div>\n        </div>\n        <div class=\"card\" style=\"margin:0;text-align:center\">\n          <div style=\"color:#64748b\">المستحق للسائقين غير الأساسيين</div>\n          <div id=\"accountsExternalDue\" style=\"font-size:28px;font-weight:800;margin-top:6px\">0 ر.س</div>\n        </div>\n        <div class=\"card\" style=\"margin:0;text-align:center\">\n          <div style=\"color:#64748b\">إجمالي المصاريف المسجلة</div>\n          <div id=\"accountsExpenses\" style=\"font-size:28px;font-weight:800;margin-top:6px\">0 ر.س</div>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"card no-print\">\n      <h2>النسخ الاحتياطي</h2>\n      <p style=\"margin-top:0;color:#64748b\">احفظ نسخة من جميع بيانات البرنامج في ملف واحد، ويمكن استعادتها لاحقًا.</p>\n      <div style=\"display:flex;gap:10px;flex-wrap:wrap\">\n        <button class=\"btn primary\" onclick=\"exportBackup()\">تنزيل نسخة احتياطية</button>\n        <label class=\"btn gray\" style=\"display:inline-flex;align-items:center;cursor:pointer\">\n          استعادة نسخة احتياطية\n          <input id=\"backupRestoreInput\" type=\"file\" accept=\".json,application/json\" class=\"hidden\" onchange=\"restoreBackupFile(this.files[0])\">\n        </label>\n      </div>\n      <div id=\"backupStatus\" style=\"margin-top:10px;color:#64748b;font-size:14px\"></div>\n    </div>\n\n    <div class=\"card\">\n      <h2>مستحقات العملاء</h2>\n      <div class=\"scroll\">\n        <table>\n          <thead><tr><th>العميل</th><th>عدد الفواتير غير المسددة</th><th>المبلغ المتبقي</th></tr></thead>\n          <tbody id=\"accountsCustomerRows\"></tbody>\n        </table>\n      </div>\n    </div>\n\n    <div class=\"card\">\n      <h2>مستحقات السائقين غير الأساسيين</h2>\n      <div class=\"scroll\">\n        <table>\n          <thead><tr><th>السائق</th><th>عدد المشاوير غير المسددة</th><th>المبلغ المستحق</th></tr></thead>\n          <tbody id=\"accountsExternalRows\"></tbody>\n        </table>\n      </div>\n    </div>\n  </div>\n\n\n  <div id=\"externalDrivers\" class=\"card home-section\">\n    <h2>سائقون غير تابعين لي</h2>\n    <div class=\"formgrid no-print\">\n      <div><label>اسم السائق الخارجي</label><input id=\"externalDriverName\" placeholder=\"اسم السائق\"></div>\n      <div><label>رقم السيارة / اللوحة</label><input id=\"externalDriverVehicle\" placeholder=\"مثال: 1234\"></div>\n      <div class=\"actions\" style=\"align-items:end\">\n        <button class=\"btn primary\" type=\"button\" onclick=\"addExternalDriver()\">إضافة السائق</button>\n      </div>\n    </div>\n    <div id=\"externalDriverButtons\" class=\"bigbuttons\"></div>\n  </div>\n\n\n<div id=\"externalDriversTable\" class=\"card home-section\">\n  <h2>الجدول المستقل للسائقين غير الأساسيين</h2>\n  <div class=\"tablewrap\">\n    <table>\n      <thead>\n        <tr>\n          <th>اسم السائق</th>\n          <th>رقم السيارة / اللوحة</th>\n          <th>عدد المشاوير</th>\n          <th>إجمالي مبالغ المشاوير</th>\n          <th>التفاصيل</th>\n        </tr>\n      </thead>\n      <tbody id=\"externalDriversRows\"></tbody>\n    </table>\n  </div>\n</div>\n\n</div>\n\n<div id=\"detailPage\" class=\"hidden\">\n  <button class=\"btn gray\" onclick=\"goHome()\">← رجوع</button>\n  <div class=\"card\" style=\"margin-top:10px\">\n    <h2 id=\"detailTitle\"></h2>\n    <div class=\"formgrid\">\n      <div><label>التاريخ</label><input id=\"date\" type=\"date\"></div>\n      <div><label>السواق</label><select id=\"driverSelect\"></select></div>\n      <div><label>العميل</label><select id=\"customerSelect\"></select></div>\n      <div><label>من</label><input id=\"from\" placeholder=\"مكان التحميل\"></div>\n      <div><label>إلى</label><input id=\"to\" placeholder=\"مكان التسليم\"></div>\n      <div><label>رقم السند</label><input id=\"delivery\" inputmode=\"numeric\"></div>\n      <div><label>الوزن</label><input id=\"weight\" type=\"number\" step=\"0.01\" placeholder=\"مثال: 25\"></div>\n      <div><label>المبلغ</label><input id=\"amount\" type=\"number\" step=\"0.01\"></div>\n      <div id=\"tripCashWrap\"><label>تحصيل قيمة المشوار</label>\n        <select id=\"tripCashStatus\">\n          <option value=\"account\">آجل / غير كاش مع السائق</option>\n          <option value=\"driver_cash\">كاش استلمه السائق</option>\n        </select>\n      </div>\n      <div id=\"externalTripPaymentWrap\" class=\"hidden\"><label>حالة سداد السائق غير الأساسي</label>\n        <select id=\"externalTripPaymentStatus\">\n          <option value=\"unpaid\">باقي - لم يتم السداد</option>\n          <option value=\"paid\">تم السداد</option>\n        </select>\n      </div>\n      <div class=\"full\"><label>صورة السند / الفاتورة من الاستديو أو ملفات واتساب</label><input id=\"photo\" type=\"file\" accept=\"image/*\"><small style=\"display:block;color:#64748b;margin-top:5px\">اضغط اختيار ملف، ثم اختر الصورة من الاستديو أو مجلد صور واتساب.</small></div>\n    </div>\n    <div class=\"actions\"><button class=\"btn primary\" onclick=\"addTrip()\">حفظ المشوار</button></div>\n  </div>\n\n  <div id=\"driverExpenses\" class=\"card hidden\">\n    <h2>مصاريف السواق</h2>\n\n    <div class=\"no-print\" style=\"margin-bottom:12px\">\n      <div class=\"formgrid\">\n        <div><label>شهر المصاريف</label><input id=\"expenseMonth\" type=\"month\"></div>\n        <div class=\"actions\" style=\"align-items:end\">\n          <button class=\"btn gray\" type=\"button\" onclick=\"applyExpenseMonth()\">عرض الشهر</button>\n          <button class=\"btn primary\" type=\"button\" onclick=\"printExpenses()\">طباعة مصاريف الشهر</button>\n        </div>\n      </div>\n    </div>\n\n    <div id=\"expensePrintHeader\" class=\"hidden\">\n      <h2 id=\"expensePrintTitle\"></h2>\n      <div id=\"expensePrintMonth\"></div>\n    </div>\n\n    <div class=\"formgrid\">\n      <div><label>التاريخ</label><input id=\"expenseDate\" type=\"date\"></div>\n      <div><label>نوع المصروف</label>\n        <select id=\"expenseType\">\n          <option>ديزل</option>\n          <option>صيانة</option>\n          <option>زيت</option>\n          <option>بنشر / كفرات</option>\n          <option>غسيل</option>\n          <option>سلفة</option>\n          <option>أخرى</option>\n        </select>\n      </div>\n      <div><label>المبلغ</label><input id=\"expenseAmount\" type=\"number\" step=\"0.01\" placeholder=\"0.00\"></div>\n      <div><label>مصدر دفع المصروف</label>\n        <select id=\"expenseCashSource\">\n          <option value=\"other\">مصدر آخر</option>\n          <option value=\"trip_cash\">من كاش المشاوير</option>\n          <option value=\"driver\">من السائق</option>\n        </select>\n      </div>\n      <div><label>ملاحظة</label><input id=\"expenseNote\" placeholder=\"تفاصيل المصروف\"></div>\n      <div class=\"full\"><label>صورة إيصال المصروف من الاستديو أو ملفات واتساب</label><input id=\"expensePhoto\" type=\"file\" accept=\"image/*\"></div>\n    </div>\n    <div class=\"actions\"><button class=\"btn primary\" onclick=\"addExpense()\">حفظ المصروف</button></div>\n\n    <div style=\"margin-top:14px;font-weight:bold\">إجمالي مصاريف السواق: <span id=\"expenseTotal\">0 ر.س</span></div>\n    <div class=\"scroll\" style=\"margin-top:10px\">\n      <table>\n        <thead><tr><th>التاريخ</th><th>نوع المصروف</th><th>المبلغ</th><th>مصدر الدفع</th><th>ملاحظة</th><th>الإيصال</th><th></th></tr></thead>\n        <tbody id=\"expenseRows\"></tbody>\n      </table>\n    </div>\n  </div>\n\n  <div id=\"printHeader\">\n    <h2 id=\"printTitle\"></h2>\n    <div id=\"printMonthLabel\"></div>\n  </div>\n\n  <div class=\"card\">\n    <div id=\"monthlyPrintControls\" class=\"no-print hidden\" style=\"margin-bottom:12px\">\n      <div class=\"formgrid\">\n        <div><label>اختر الشهر الميلادي</label><input id=\"reportMonth\" type=\"month\"></div>\n        <div class=\"actions\" style=\"align-items:end\">\n          <button class=\"btn primary\" onclick=\"applyReportMonth()\">عرض الشهر</button>\n          <button class=\"btn gray\" onclick=\"printCurrentTable()\">طباعة الكشف الحالي</button>\n          <button id=\"printDriverMonthlyFullBtn\" class=\"btn primary hidden\" type=\"button\" onclick=\"printDriverMonthlyFull()\">طباعة مشاوير + مصاريف + سلف + كاش الشهر</button>\n          <select id=\"driverCustomerReportSelect\" class=\"hidden\" style=\"min-width:170px\"><option value=\"\">اختر العميل</option></select>\n          <button id=\"printDriverByCustomersBtn\" class=\"btn primary hidden\" onclick=\"printDriverForCustomer()\">كشف السائق لهذا العميل</button>\n        </div>\n      </div>\n    </div>\n    <h2>جدول المشاوير</h2>\n    <div class=\"scroll\">\n      <table>\n        <thead>\n          <tr><th>التاريخ</th><th>السواق</th><th>العميل</th><th>من</th><th>إلى</th><th>رقم السند</th><th>الوزن</th><th>الصورة</th><th>المبلغ</th><th>تحصيل المشوار</th><th>حالة السداد</th><th></th></tr>\n        </thead>\n        \n    <div id=\"driverTripTotalBox\" class=\"card hidden\" style=\"text-align:center\">\n      <div style=\"font-size:16px;color:#475569;margin-bottom:6px\">إجمالي مبالغ مشاوير السائق</div>\n      <div id=\"driverTripTotal\" style=\"font-size:30px;font-weight:800\">0 ر.س</div>\n    </div>\n<tbody id=\"rows\"></tbody>\n      </table>\n    </div>\n  </div>\n</div>\n\n<div id=\"groupedDriverReport\">\n  <div id=\"groupedDriverReportContent\"></div>\n</div>\n\n<div id=\"monthlyDriverReport\">\n  <div id=\"monthlyDriverReportContent\"></div>\n</div>\n\n</main>\n<div id=\"modal\" class=\"modal\" onclick=\"this.classList.remove('on')\"><img id=\"big\"></div>\n\n<script>\nconst SEED = {\"drivers\": [{\"id\": 1, \"name\": \"محمد\", \"vehicle\": \"7616\"}], \"customers\": [{\"id\": 1, \"name\": \"المصنع الحديث\"}, {\"id\": 2, \"name\": \"مصنع الأسلاك\"}, {\"id\": 3, \"name\": \"مخرج 6\"}], \"trips\": [{\"id\": 1, \"driverId\": 1, \"customerId\": 3, \"date\": \"2026-09-08\", \"from\": \"\", \"to\": \"\", \"delivery\": \"80028159\", \"amount\": \"\", \"image\": \"data:image/jpeg;base64,\"}]};\nlet db;\ntry { db = JSON.parse(localStorage.getItem('abdullahTransport3')) || SEED; }\ncatch(e) { db = SEED; }\nif(!db.expenses) db.expenses=[];\nif(!db.externalDrivers) db.externalDrivers=[];\nif(!db.taxInvoices) db.taxInvoices=[];\nif(!db.monthlyRosters || typeof db.monthlyRosters!=='object') db.monthlyRosters={};\n\nlet mode = 'drivers';\nlet detailType = null;\nlet detailId = null;\nlet selectedCustomerMonth = '';\nlet selectedDriverMonth = '';\nlet selectedExpenseMonth = '';\nconst initialGregorianMonth = new Date().toISOString().slice(0,7);\nlet homeMonth = initialGregorianMonth;\nlet homeDriverMonth = homeMonth;\nlet homeCustomerMonth = homeMonth;\nconst $ = id => document.getElementById(id);\n\n// أرشيف شهري مستقل للسواقين والعملاء. يحتفظ بصورة الأسماء كما كانت في كل شهر.\nfunction monthKeyFromDate(date) { return String(date||'').slice(0,7); }\nfunction rosterHas(arr,id) { return (arr||[]).some(x=>Number(x.id)===Number(id)); }\nfunction driverSnapshot(id) {\n  const d=db.drivers.find(x=>Number(x.id)===Number(id));\n  return d ? {id:d.id,name:d.name,vehicle:d.vehicle||''} : null;\n}\nfunction customerSnapshot(id) {\n  const c=db.customers.find(x=>Number(x.id)===Number(id));\n  return c ? {id:c.id,name:c.name} : null;\n}\nfunction ensureMonthlyRoster(month, includeCurrent=false) {\n  if(!month) return {drivers:[],customers:[]};\n  if(!db.monthlyRosters[month]) db.monthlyRosters[month]={drivers:[],customers:[],createdAt:new Date().toISOString()};\n  const r=db.monthlyRosters[month];\n  if(!Array.isArray(r.drivers)) r.drivers=[];\n  if(!Array.isArray(r.customers)) r.customers=[];\n\n  // استرجاع السجل التاريخي من المشاوير الموجودة بدون خلطه بقائمة اليوم.\n  db.trips.filter(t=>monthKeyFromDate(t.date)===month).forEach(t=>{\n    if(t.driverId && !rosterHas(r.drivers,t.driverId)) { const d=driverSnapshot(t.driverId); if(d) r.drivers.push(d); }\n    if(t.customerId && !rosterHas(r.customers,t.customerId)) { const c=customerSnapshot(t.customerId); if(c) r.customers.push(c); }\n  });\n  (db.taxInvoices||[]).filter(inv=>monthKeyFromDate(inv.date)===month).forEach(inv=>{\n    if(inv.customerId && !rosterHas(r.customers,inv.customerId)) { const c=customerSnapshot(inv.customerId); if(c) r.customers.push(c); }\n  });\n\n  if(includeCurrent) {\n    db.drivers.forEach(d=>{ if(!rosterHas(r.drivers,d.id)) r.drivers.push({id:d.id,name:d.name,vehicle:d.vehicle||''}); });\n    db.customers.forEach(c=>{ if(!rosterHas(r.customers,c.id)) r.customers.push({id:c.id,name:c.name}); });\n  }\n  return r;\n}\nfunction archiveTripRoster(trip) {\n  const month=monthKeyFromDate(trip.date);\n  if(!month) return;\n  const r=ensureMonthlyRoster(month,false);\n  if(trip.driverId && !rosterHas(r.drivers,trip.driverId)) { const d=driverSnapshot(trip.driverId); if(d) r.drivers.push(d); }\n  if(trip.customerId && !rosterHas(r.customers,trip.customerId)) { const c=customerSnapshot(trip.customerId); if(c) r.customers.push(c); }\n}\nfunction archiveCurrentName(type,item) {\n  const month=initialGregorianMonth;\n  const r=ensureMonthlyRoster(month,true);\n  if(type==='driver' && !rosterHas(r.drivers,item.id)) r.drivers.push({id:item.id,name:item.name,vehicle:item.vehicle||''});\n  if(type==='customer' && !rosterHas(r.customers,item.id)) r.customers.push({id:item.id,name:item.name});\n}\nfunction removeFromCurrentRoster(type,id) {\n  const r=ensureMonthlyRoster(initialGregorianMonth,false);\n  if(type==='driver') r.drivers=r.drivers.filter(x=>Number(x.id)!==Number(id));\n  if(type==='customer') r.customers=r.customers.filter(x=>Number(x.id)!==Number(id));\n}\n\n// ترحيل البيانات القديمة إلى أرشيف شهري، مع إنشاء سجل الشهر الحالي.\n(function migrateMonthlyRosters(){\n  const months=new Set();\n  db.trips.forEach(t=>{const m=monthKeyFromDate(t.date); if(m) months.add(m);});\n  (db.taxInvoices||[]).forEach(inv=>{const m=monthKeyFromDate(inv.date); if(m) months.add(m);});\n  months.forEach(m=>ensureMonthlyRoster(m,false));\n  ensureMonthlyRoster(initialGregorianMonth,true);\n  try { localStorage.setItem('abdullahTransport3', JSON.stringify(db)); } catch(e) {}\n})();\n\nfunction formatGregorianMonth(month) {\n  if(!month) return 'كل الأشهر';\n  const parts=month.split('-').map(Number);\n  if(parts.length!==2 || !parts[0] || !parts[1]) return month;\n  const d=new Date(parts[0],parts[1]-1,1,12,0,0);\n  return new Intl.DateTimeFormat('ar-SA-u-ca-gregory',{month:'long',year:'numeric'}).format(d);\n}\n\nfunction setHomeMonth(value) {\n  homeMonth=value || initialGregorianMonth;\n  homeDriverMonth=homeMonth;\n  homeCustomerMonth=homeMonth;\n  renderHome();\n}\nfunction setHomeDriverMonth(value) { setHomeMonth(value); }\nfunction setHomeCustomerMonth(value) { setHomeMonth(value); }\n\nfunction openDetailForMonth(type,id,month) {\n  detailType=type; detailId=id;\n  $('home').classList.add('hidden');\n  $('detailPage').classList.remove('hidden');\n  $('date').value=new Date().toISOString().slice(0,10);\n  if($('expenseDate')) $('expenseDate').value=new Date().toISOString().slice(0,10);\n  if(type==='customer') selectedCustomerMonth=month;\n  if(type==='driver' || type==='externalDriver') selectedDriverMonth=month;\n  if(type==='driver') { selectedExpenseMonth=month; if($('expenseMonth')) $('expenseMonth').value=month; }\n  if($('reportMonth')) $('reportMonth').value=month;\n  renderDetail();\n}\n\nfunction save() {\n  ensureMonthlyRoster(initialGregorianMonth,true);\n  localStorage.setItem('abdullahTransport3', JSON.stringify(db));\n  renderHome();\n  if(detailType) renderDetail();\n}\n\nfunction nextId(arr) { return arr.length ? Math.max(...arr.map(x=>x.id||0))+1 : 1; }\nfunction esc(x) { return String(x??'').replace(/[&<>\"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[m])); }\nfunction expensePaymentSource(e) {\n  const src = e.paymentSource || (e.paidFromTripCash ? 'trip_cash' : 'other');\n  if(src==='trip_cash') return 'من كاش المشاوير';\n  if(src==='driver') return 'من السائق';\n  return 'مصدر آخر';\n}\n\nfunction showHomeMode(m) {\n  mode=m;\n  const map={drivers:'driversHome',customers:'customersHome',taxInvoices:'taxInvoicesHome',accounts:'accountsHome',external:'externalDrivers'};\n  $('tabDrivers').classList.toggle('active',m==='drivers');\n  $('tabCustomers').classList.toggle('active',m==='customers');\n  $('tabTaxInvoices').classList.toggle('active',m==='taxInvoices');\n  $('tabAccounts').classList.toggle('active',m==='accounts');\n  if($('tabExternal')) $('tabExternal').classList.toggle('active',m==='external');\n  // الصفحة الرئيسية الآن صفحة واحدة؛ لا نخفي الأقسام، فقط ننتقل للقسم المطلوب.\n  $('driversHome').classList.remove('hidden');\n  $('customersHome').classList.remove('hidden');\n  $('taxInvoicesHome').classList.remove('hidden');\n  $('accountsHome').classList.remove('hidden');\n  if(m==='taxInvoices') renderTaxInvoices();\n  if(m==='accounts') renderAccounts();\n  const target=$(map[m]);\n  if(target) setTimeout(()=>target.scrollIntoView({behavior:'smooth',block:'start'}),30);\n}\n\nfunction renderHome() {\n  homeDriverMonth=homeMonth;\n  homeCustomerMonth=homeMonth;\n  if($('homeMonth')) $('homeMonth').value=homeMonth;\n  if($('homeMonthName')) $('homeMonthName').textContent='عرض بيانات: '+formatGregorianMonth(homeMonth);\n\n  if($('driverMonthlyTitle')) $('driverMonthlyTitle').textContent='قائمة السواقين لشهر '+formatGregorianMonth(homeDriverMonth);\n  if($('customerMonthlyTitle')) $('customerMonthlyTitle').textContent='قائمة العملاء لشهر '+formatGregorianMonth(homeCustomerMonth);\n\n  if($('driverMonthlyRows')) {\n    const monthlyTrips=db.trips.filter(t=>monthKeyFromDate(t.date)===homeDriverMonth && !t.externalDriverId);\n    const roster=ensureMonthlyRoster(homeDriverMonth, homeDriverMonth===initialGregorianMonth);\n    const rows=roster.drivers.map(d=>{\n      const trips=monthlyTrips.filter(t=>Number(t.driverId)===Number(d.id));\n      const total=trips.reduce((sum,t)=>sum+Number(t.amount||0),0);\n      return {d,trips,total};\n    });\n    $('driverMonthlyRows').innerHTML=rows.length ? rows.map(x=>`<tr><td>${esc(x.d.name)}</td><td>${esc(x.d.vehicle||'—')}</td><td>${x.trips.length}</td><td>${x.total.toLocaleString('ar-SA',{maximumFractionDigits:2})} ر.س</td><td><button class=\"btn primary\" onclick=\"openDetailForMonth('driver',${x.d.id},'${homeDriverMonth}')\">فتح</button></td></tr>`).join('') : '<tr><td colspan=\"5\" class=\"empty\">لا توجد بيانات سواقين محفوظة لهذا الشهر الميلادي</td></tr>';\n  }\n\n  if($('customerMonthlyRows')) {\n    const monthlyTrips=db.trips.filter(t=>monthKeyFromDate(t.date)===homeCustomerMonth);\n    const roster=ensureMonthlyRoster(homeCustomerMonth, homeCustomerMonth===initialGregorianMonth);\n    const rows=roster.customers.map(c=>{\n      const trips=monthlyTrips.filter(t=>Number(t.customerId)===Number(c.id));\n      const total=trips.reduce((sum,t)=>sum+Number(t.amount||0),0);\n      return {c,trips,total};\n    });\n    $('customerMonthlyRows').innerHTML=rows.length ? rows.map(x=>`<tr><td>${esc(x.c.name)}</td><td>${x.trips.length}</td><td>${x.total.toLocaleString('ar-SA',{maximumFractionDigits:2})} ر.س</td><td><button class=\"btn primary\" onclick=\"openDetailForMonth('customer',${x.c.id},'${homeCustomerMonth}')\">فتح</button></td></tr>`).join('') : '<tr><td colspan=\"4\" class=\"empty\">لا توجد بيانات عملاء محفوظة لهذا الشهر الميلادي</td></tr>';\n  }\n\n  $('driverButtons').innerHTML = db.drivers.length ? db.drivers.map(d =>\n    `<div class=\"driver-card\">\n      <button class=\"bigbtn\" onclick=\"openDetail('driver',${d.id})\">${esc(d.name)}<small>السيارة / المقطورة: ${esc(d.vehicle||'—')}</small></button>\n      <button class=\"delete-driver-btn\" type=\"button\" onclick=\"event.stopPropagation(); deleteDriver(${d.id})\">حذف السائق</button>\n    </div>`\n  ).join('') : '<div class=\"empty\">لا يوجد سواقين</div>';\n\n  $('customerButtons').innerHTML = db.customers.length ? db.customers.map(c =>\n    `<div class=\"driver-card\">\n      <button class=\"bigbtn\" onclick=\"openDetail('customer',${c.id})\">${esc(c.name)}<small>${db.trips.filter(t=>t.customerId===c.id).length} مشوار</small></button>\n      <button class=\"delete-driver-btn\" type=\"button\" onclick=\"event.stopPropagation(); deleteCustomer(${c.id})\">حذف العميل</button>\n    </div>`\n  ).join('') : '<div class=\"empty\">لا يوجد عملاء</div>';\n  $('externalDriverButtons').innerHTML = db.externalDrivers.map(d=>`\n    <div class=\"driver-card\">\n      <button class=\"bigbtn\" onclick=\"openDetail('externalDriver',${d.id})\">\n        <strong>${esc(d.name)}</strong>\n        <span>${esc(d.vehicle||'')}</span>\n      </button>\n      <button class=\"delete-driver-btn\" type=\"button\" onclick=\"event.stopPropagation(); deleteExternalDriver(${d.id})\">حذف السائق</button>\n    </div>`).join('') || '<div class=\"empty\">لا يوجد سائقون خارجيون مسجلون</div>';\n\n  $('externalDriversRows').innerHTML = db.externalDrivers.map(d=>{\n    const trips = db.trips.filter(t=>t.externalDriverId===d.id);\n    const total = trips.reduce((sum,t)=>sum+Number(t.amount||0),0);\n    return `<tr>\n      <td>${esc(d.name)}</td>\n      <td>${esc(d.vehicle||'—')}</td>\n      <td>${trips.length}</td>\n      <td>${total.toLocaleString('ar-SA',{maximumFractionDigits:2})} ر.س</td>\n      <td><button class=\"btn primary\" onclick=\"openDetail('externalDriver',${d.id})\">فتح جدول السائق</button></td>\n    </tr>`;\n  }).join('') || '<tr><td colspan=\"5\" class=\"empty\">لا يوجد سائقون غير أساسيين مسجلون</td></tr>';\n\n  renderTaxInvoices();\n  renderAccounts();\n}\n\n\n\nfunction exportBackup(){\n  try{\n    const payload = {\n      app: 'Madad Alasimah Transport',\n      version: 1,\n      exportedAt: new Date().toISOString(),\n      storageKey: 'abdullahTransport3',\n      data: db\n    };\n    const blob = new Blob([JSON.stringify(payload,null,2)], {type:'application/json;charset=utf-8'});\n    const a = document.createElement('a');\n    const stamp = new Date().toISOString().slice(0,10);\n    a.href = URL.createObjectURL(blob);\n    a.download = `madad_alasimah_backup_${stamp}.json`;\n    document.body.appendChild(a);\n    a.click();\n    a.remove();\n    setTimeout(()=>URL.revokeObjectURL(a.href),1000);\n    if($('backupStatus')) $('backupStatus').textContent='تم إنشاء النسخة الاحتياطية بنجاح.';\n  }catch(e){\n    if($('backupStatus')) $('backupStatus').textContent='تعذر إنشاء النسخة الاحتياطية.';\n    alert('تعذر إنشاء النسخة الاحتياطية');\n  }\n}\n\nfunction restoreBackupFile(file){\n  if(!file) return;\n  const reader = new FileReader();\n  reader.onload = function(){\n    try{\n      const parsed = JSON.parse(reader.result);\n      const restored = parsed && parsed.data ? parsed.data : parsed;\n      if(!restored || typeof restored!=='object' || !Array.isArray(restored.trips) || !Array.isArray(restored.customers)){\n        throw new Error('invalid');\n      }\n      if(!confirm('سيتم استبدال البيانات الحالية بالنسخة الاحتياطية. هل تريد المتابعة؟')) {\n        $('backupRestoreInput').value='';\n        return;\n      }\n      db = restored;\n      if(!db.expenses) db.expenses=[];\n      if(!db.externalDrivers) db.externalDrivers=[];\n      if(!db.taxInvoices) db.taxInvoices=[];\n      localStorage.setItem('abdullahTransport3', JSON.stringify(db));\n      renderHome();\n      if(detailType) renderDetail();\n      if($('backupStatus')) $('backupStatus').textContent='تمت استعادة النسخة الاحتياطية بنجاح.';\n      alert('تمت استعادة البيانات بنجاح');\n    }catch(e){\n      if($('backupStatus')) $('backupStatus').textContent='ملف النسخة الاحتياطية غير صالح.';\n      alert('ملف النسخة الاحتياطية غير صالح');\n    }finally{\n      if($('backupRestoreInput')) $('backupRestoreInput').value='';\n    }\n  };\n  reader.readAsText(file,'utf-8');\n}\n\nfunction renderAccounts() {\n  if(!$('accountsHome')) return;\n\n  const unpaidInvoices = db.taxInvoices.filter(inv=>inv.paymentStatus!=='paid');\n  const paidInvoices = db.taxInvoices.filter(inv=>inv.paymentStatus==='paid');\n  const receivables = unpaidInvoices.reduce((s,inv)=>s+Number(inv.amount||0),0);\n  const collected = paidInvoices.reduce((s,inv)=>s+Number(inv.amount||0),0);\n  const externalDueTrips = db.trips.filter(t=>t.externalDriverId && t.externalPaymentStatus!=='paid');\n  const externalDue = externalDueTrips.reduce((s,t)=>s+Number(t.amount||0),0);\n  const expenses = db.expenses.reduce((s,e)=>s+Number(e.amount||0),0);\n\n  $('accountsReceivables').textContent = receivables.toLocaleString('ar-SA',{maximumFractionDigits:2})+' ر.س';\n  $('accountsCollected').textContent = collected.toLocaleString('ar-SA',{maximumFractionDigits:2})+' ر.س';\n  $('accountsExternalDue').textContent = externalDue.toLocaleString('ar-SA',{maximumFractionDigits:2})+' ر.س';\n  $('accountsExpenses').textContent = expenses.toLocaleString('ar-SA',{maximumFractionDigits:2})+' ر.س';\n\n  const customerRows = db.customers.map(c=>{\n    const invs = unpaidInvoices.filter(inv=>inv.customerId===c.id);\n    const total = invs.reduce((s,inv)=>s+Number(inv.amount||0),0);\n    if(!invs.length && !total) return '';\n    return `<tr>\n      <td>${esc(c.name)}</td>\n      <td>${invs.length}</td>\n      <td>${total.toLocaleString('ar-SA',{maximumFractionDigits:2})} ر.س</td>\n    </tr>`;\n  }).filter(Boolean).join('');\n  $('accountsCustomerRows').innerHTML = customerRows || '<tr><td colspan=\"3\" class=\"empty\">لا توجد مستحقات غير مسددة على العملاء</td></tr>';\n\n  const externalRows = db.externalDrivers.map(d=>{\n    const trips = externalDueTrips.filter(t=>t.externalDriverId===d.id);\n    const total = trips.reduce((s,t)=>s+Number(t.amount||0),0);\n    if(!trips.length && !total) return '';\n    return `<tr>\n      <td>${esc(d.name)}</td>\n      <td>${trips.length}</td>\n      <td>${total.toLocaleString('ar-SA',{maximumFractionDigits:2})} ر.س</td>\n    </tr>`;\n  }).filter(Boolean).join('');\n  $('accountsExternalRows').innerHTML = externalRows || '<tr><td colspan=\"3\" class=\"empty\">لا توجد مستحقات غير مسددة للسائقين غير الأساسيين</td></tr>';\n}\n\nfunction renderTaxInvoices() {\n  const sel=$('taxInvoiceCustomer');\n  if(sel) {\n    const current=sel.value;\n    sel.innerHTML='<option value=\"\">اختر العميل</option>'+db.customers.map(c=>`<option value=\"${c.id}\">${esc(c.name)}</option>`).join('');\n    if(current) sel.value=current;\n  }\n  const rows=$('taxInvoiceRows');\n  if(!rows) return;\n  rows.innerHTML=db.taxInvoices.slice().reverse().map(inv=>{\n    const c=db.customers.find(x=>x.id===inv.customerId);\n    let fileCell='—';\n    if(inv.fileData) {\n      if((inv.fileType||'').startsWith('image/')) fileCell=`<img class=\"thumb\" src=\"${inv.fileData}\" onclick=\"showImg(this.src)\" title=\"فتح الفاتورة\">`;\n      else fileCell=`<button class=\"btn gray\" onclick=\"openStoredFile(${inv.id})\">فتح PDF</button>`;\n    }\n    const status = inv.paymentStatus==='paid' ? 'تم السداد' : 'باقي - لم يتم السداد';\n    return `<tr><td>${esc(inv.date)}</td><td>${esc(c?.name||'')}</td><td>${esc(inv.number)}</td><td>${inv.amount?esc(inv.amount)+' ر.س':'—'}</td><td>${status}</td><td>${fileCell}</td><td>${esc(inv.note||'')}</td><td><button class=\"btn red\" onclick=\"deleteTaxInvoice(${inv.id})\">حذف</button></td></tr>`;\n  }).join('') || '<tr><td colspan=\"8\" class=\"empty\">لا توجد فواتير ضريبية محفوظة</td></tr>';\n}\n\nasync function addTaxInvoice() {\n  const customerId=Number($('taxInvoiceCustomer').value);\n  const number=$('taxInvoiceNumber').value.trim();\n  if(!customerId) return alert('اختر العميل');\n  if(!number) return alert('اكتب رقم الفاتورة');\n  const f=$('taxInvoiceFile').files[0];\n  if(!f) return alert('اختر صورة أو ملف الفاتورة');\n  if(f.size>2500000) return alert('حجم الملف كبير. اختر فاتورة أقل من 2.5 ميجابايت حتى تُحفظ داخل البرنامج.');\n  const fileData=await new Promise(resolve=>{const r=new FileReader(); r.onload=()=>resolve(r.result); r.readAsDataURL(f);});\n  db.taxInvoices.push({\n    id:nextId(db.taxInvoices), customerId, number,\n    date:$('taxInvoiceDate').value, amount:$('taxInvoiceAmount').value,\n    paymentStatus:$('taxInvoicePaymentStatus').value,\n    note:$('taxInvoiceNote').value.trim(), fileData,\n    fileType:f.type||'', fileName:f.name||''\n  });\n  $('taxInvoiceNumber').value=''; $('taxInvoiceAmount').value=''; $('taxInvoiceNote').value=''; $('taxInvoiceFile').value=''; $('taxInvoicePaymentStatus').value='unpaid';\n  save();\n  showHomeMode('taxInvoices');\n}\n\nfunction openStoredFile(id) {\n  const inv=db.taxInvoices.find(x=>x.id===id);\n  if(!inv?.fileData) return;\n  const w=window.open();\n  if(w) w.location.href=inv.fileData;\n}\n\nfunction deleteTaxInvoice(id) {\n  if(confirm('حذف الفاتورة الضريبية المحفوظة؟')) {\n    db.taxInvoices=db.taxInvoices.filter(x=>x.id!==id);\n    save();\n    showHomeMode('taxInvoices');\n  }\n}\n\nfunction addDriver() {\n  const name=$('newDriver').value.trim();\n  if(!name) return alert('اكتب اسم السواق');\n  const item={id:nextId(db.drivers),name,vehicle:$('newVehicle').value.trim()};\n  db.drivers.push(item);\n  archiveCurrentName('driver',item);\n  $('newDriver').value=''; $('newVehicle').value=''; save();\n}\n\nfunction deleteDriver(id) {\n  const d=db.drivers.find(x=>x.id===id);\n  if(!d) return;\n  const tripCount=db.trips.filter(t=>t.driverId===id).length;\n  const expenseCount=db.expenses.filter(e=>e.driverId===id).length;\n  if(tripCount || expenseCount) {\n    return alert(`لا يمكن حذف السائق ${d.name} لأن لديه بيانات محفوظة (${tripCount} مشوار و ${expenseCount} مصروف). احذف بياناته أولاً أو احتفظ به حتى لا تضيع السجلات.`);\n  }\n  if(confirm(`هل تريد حذف السائق ${d.name}؟`)) {\n    db.drivers=db.drivers.filter(x=>x.id!==id);\n    removeFromCurrentRoster('driver',id);\n    save();\n  }\n}\n\nfunction deleteExternalDriver(id) {\n  const d=db.externalDrivers.find(x=>x.id===id);\n  if(!d) return;\n  const tripCount=db.trips.filter(t=>t.externalDriverId===id).length;\n  if(tripCount) {\n    return alert(`لا يمكن حذف السائق ${d.name} لأن لديه ${tripCount} مشوار محفوظ. احذف مشاويره أولاً أو احتفظ به حتى لا تضيع السجلات.`);\n  }\n  if(confirm(`هل تريد حذف السائق ${d.name}؟`)) {\n    db.externalDrivers=db.externalDrivers.filter(x=>x.id!==id);\n    save();\n  }\n}\n\nfunction addCustomer() {\n  const name=$('newCustomer').value.trim();\n  if(!name) return alert('اكتب اسم العميل');\n  const item={id:nextId(db.customers),name};\n  db.customers.push(item);\n  archiveCurrentName('customer',item);\n  $('newCustomer').value=''; save();\n}\n\nfunction deleteCustomer(id) {\n  const c=db.customers.find(x=>x.id===id);\n  if(!c) return;\n  const tripCount=db.trips.filter(t=>t.customerId===id).length;\n  const invoiceCount=db.taxInvoices.filter(inv=>inv.customerId===id).length;\n  if(tripCount || invoiceCount) {\n    return alert(`لا يمكن حذف العميل ${c.name} لأن لديه بيانات محفوظة (${tripCount} مشوار و ${invoiceCount} فاتورة ضريبية). احذف بياناته أولاً أو احتفظ به حتى لا تضيع السجلات.`);\n  }\n  if(confirm(`هل تريد حذف العميل ${c.name}؟`)) {\n    db.customers=db.customers.filter(x=>x.id!==id);\n    removeFromCurrentRoster('customer',id);\n    save();\n  }\n}\n\nfunction openAllDrivers() {\n  detailType='allDrivers';\n  detailId=null;\n  $('home').classList.add('hidden');\n  $('detailPage').classList.remove('hidden');\n  selectedDriverMonth = homeDriverMonth || initialGregorianMonth;\n  if($('reportMonth')) $('reportMonth').value = selectedDriverMonth;\n  renderDetail();\n}\n\nfunction openAllCustomers() {\n  detailType='allCustomers';\n  detailId=null;\n  $('home').classList.add('hidden');\n  $('detailPage').classList.remove('hidden');\n  selectedCustomerMonth = homeCustomerMonth || initialGregorianMonth;\n  if($('reportMonth')) $('reportMonth').value = selectedCustomerMonth;\n  renderDetail();\n}\n\nfunction openDetail(type,id) {\n  detailType=type; detailId=id;\n  $('home').classList.add('hidden');\n  $('detailPage').classList.remove('hidden');\n  $('date').value=new Date().toISOString().slice(0,10);\n  if($('expenseDate')) $('expenseDate').value=new Date().toISOString().slice(0,10);\n  const currentMonth = new Date().toISOString().slice(0,7);\n  if(type==='customer') selectedCustomerMonth = currentMonth;\n  if(type==='driver') {\n    selectedDriverMonth = currentMonth;\n    selectedExpenseMonth = currentMonth;\n    if($('expenseMonth')) $('expenseMonth').value = currentMonth;\n  }\n  if(type==='externalDriver') selectedDriverMonth = currentMonth;\n  if($('reportMonth')) $('reportMonth').value = currentMonth;\n  renderDetail();\n}\n\nfunction goHome() {\n  detailType=null; detailId=null;\n  $('detailPage').classList.add('hidden');\n  $('home').classList.remove('hidden');\n  showHomeMode(mode);\n}\n\nfunction fillSelects() {\n  $('driverSelect').innerHTML = db.drivers.map(d=>`<option value=\"${d.id}\">${esc(d.name)}${d.vehicle?' - '+esc(d.vehicle):''}</option>`).join('');\n  $('customerSelect').innerHTML = db.customers.map(c=>`<option value=\"${c.id}\">${esc(c.name)}</option>`).join('');\n  if(detailType==='driver') $('driverSelect').value=detailId;\n  if(detailType==='customer') $('customerSelect').value=detailId;\n  if(detailType==='allCustomers') {\n    $('driverSelect').disabled=false;\n    $('customerSelect').disabled=false;\n  }\n}\n\nfunction renderDetail() {\n  fillSelects();\n  let trips=[];\n  if(detailType==='driver') {\n    const d=db.drivers.find(x=>x.id===detailId);\n    $('detailTitle').textContent='جدول السواق: '+d.name+(d.vehicle?' — '+d.vehicle:'');\n    trips=db.trips.filter(t=>t.driverId===detailId);\n    if(selectedDriverMonth) trips=trips.filter(t=>(t.date||'').slice(0,7)===selectedDriverMonth);\n    $('printTitle').textContent='كشف مشاوير السواق: '+(d?.name||'');\n    $('printMonthLabel').textContent='الشهر الميلادي: '+formatGregorianMonth(selectedDriverMonth);\n  } else if(detailType==='allDrivers') {\n    $('detailTitle').textContent='الجدول العام لجميع السواقين';\n    trips=db.trips.slice();\n    if(selectedDriverMonth) trips=trips.filter(t=>(t.date||'').slice(0,7)===selectedDriverMonth);\n    $('printTitle').textContent='الكشف العام لجميع السواقين';\n    $('printMonthLabel').textContent='الشهر الميلادي: '+formatGregorianMonth(selectedDriverMonth);\n  } else if(detailType==='customer') {\n    const c=db.customers.find(x=>x.id===detailId);\n    $('detailTitle').textContent='جدول العميل: '+c.name;\n    trips=db.trips.filter(t=>t.customerId===detailId);\n    if(selectedCustomerMonth) trips=trips.filter(t=>(t.date||'').slice(0,7)===selectedCustomerMonth);\n    $('printTitle').textContent='كشف مشاوير العميل: '+(c?.name||'');\n    $('printMonthLabel').textContent='الشهر الميلادي: '+formatGregorianMonth(selectedCustomerMonth);\n  } else if(detailType==='allCustomers') {\n    $('detailTitle').textContent='الجدول العام لجميع العملاء';\n    trips=db.trips.slice();\n    if(selectedCustomerMonth) trips=trips.filter(t=>(t.date||'').slice(0,7)===selectedCustomerMonth);\n    $('printTitle').textContent='الكشف العام لجميع العملاء';\n    $('printMonthLabel').textContent='الشهر الميلادي: '+formatGregorianMonth(selectedCustomerMonth);\n  } else if(detailType==='externalDriver') {\n    const d=db.externalDrivers.find(x=>x.id===detailId);\n    $('detailTitle').textContent='جدول السائق غير الأساسي: '+(d?.name||'')+(d?.vehicle?' — '+d.vehicle:'');\n    trips=db.trips.filter(t=>t.externalDriverId===detailId);\n    if(selectedDriverMonth) trips=trips.filter(t=>(t.date||'').slice(0,7)===selectedDriverMonth);\n    $('printTitle').textContent='كشف مشاوير السائق غير الأساسي: '+(d?.name||'');\n    $('printMonthLabel').textContent='الشهر الميلادي: '+formatGregorianMonth(selectedDriverMonth);\n  }\n  $('monthlyPrintControls').classList.remove('hidden');\n  if($('reportMonth')) $('reportMonth').value = (detailType==='driver' || detailType==='allDrivers' || detailType==='externalDriver') ? selectedDriverMonth : selectedCustomerMonth;\n  if($('printDriverByCustomersBtn')) $('printDriverByCustomersBtn').classList.toggle('hidden', detailType!=='driver');\n  if($('printDriverMonthlyFullBtn')) $('printDriverMonthlyFullBtn').classList.toggle('hidden', detailType!=='driver');\n  if($('driverCustomerReportSelect')) {\n    $('driverCustomerReportSelect').classList.toggle('hidden', detailType!=='driver');\n    if(detailType==='driver') {\n      const customerIds = [...new Set(db.trips.filter(t=>t.driverId===detailId).map(t=>t.customerId))];\n      $('driverCustomerReportSelect').innerHTML = '<option value=\"\">اختر العميل</option>' + customerIds.map(cid=>{\n        const c=db.customers.find(x=>x.id===cid);\n        return c ? `<option value=\"${c.id}\">${esc(c.name)}</option>` : '';\n      }).join('');\n    }\n  }\n\n  if($('externalTripPaymentWrap')) $('externalTripPaymentWrap').classList.toggle('hidden', detailType!=='externalDriver');\n  if($('tripCashWrap')) $('tripCashWrap').classList.toggle('hidden', detailType==='externalDriver');\n\n  // إظهار المصاريف فقط داخل صفحة السائق الفردية\n  $('driverExpenses').classList.toggle('hidden', detailType!=='driver');\n  if(detailType==='driver') {\n    let expenses = db.expenses.filter(e=>e.driverId===detailId);\n    if(selectedExpenseMonth) expenses = expenses.filter(e=>(e.date||'').slice(0,7)===selectedExpenseMonth);\n    expenses = expenses.slice().reverse();\n    const total = expenses.reduce((s,e)=>s+Number(e.amount||0),0);\n    $('expenseTotal').textContent = total.toLocaleString('ar-SA',{maximumFractionDigits:2})+' ر.س';\n    const d=db.drivers.find(x=>x.id===detailId);\n    $('expensePrintTitle').textContent='كشف مصاريف السواق: '+(d?.name||'');\n    $('expensePrintMonth').textContent='الشهر الميلادي: '+formatGregorianMonth(selectedExpenseMonth);\n    if($('expenseMonth')) $('expenseMonth').value = selectedExpenseMonth;\n    $('expenseRows').innerHTML = expenses.map(e=>`<tr>\n      <td>${esc(e.date)}</td>\n      <td>${esc(e.type)}</td>\n      <td>${esc(e.amount)} ر.س</td>\n      <td>${expensePaymentSource(e)}</td>\n      <td>${esc(e.note)}</td>\n      <td>${e.image?`<img class=\"thumb\" src=\"${e.image}\" onclick=\"showImg(this.src)\">`:'—'}</td>\n      <td><button class=\"btn red\" onclick=\"deleteExpense(${e.id})\">حذف</button></td>\n    </tr>`).join('') || '<tr><td colspan=\"7\" class=\"empty\">لا توجد مصاريف مسجلة لهذا السواق</td></tr>';\n  }\n\n  const tripTotalBox = $('driverTripTotalBox');\n  if(detailType==='driver' || detailType==='externalDriver') {\n    const totalTripsAmount = trips.reduce((s,t)=>s+Number(t.amount||0),0);\n    tripTotalBox.classList.remove('hidden');\n    $('driverTripTotal').textContent = totalTripsAmount.toLocaleString('ar-SA',{maximumFractionDigits:2})+' ر.س';\n  } else {\n    tripTotalBox.classList.add('hidden');\n  }\n\n  $('rows').innerHTML = trips.slice().reverse().map(t=>{\n    const d=t.externalDriverId ? db.externalDrivers.find(x=>x.id===t.externalDriverId) : db.drivers.find(x=>x.id===t.driverId);\n    const c=db.customers.find(x=>x.id===t.customerId);\n    const paymentStatusText = t.externalPaymentStatus==='paid' ? 'تم السداد' : 'باقي - لم يتم السداد';\n    const cashCollectionText = t.externalDriverId ? '—' : (t.cashWithDriver ? 'كاش مع السائق' : 'آجل / غير كاش');\n    const paymentCell = t.externalDriverId\n      ? `<span class=\"payment-status-screen\"><button class=\"btn ${t.externalPaymentStatus==='paid'?'gray':'primary'}\" onclick=\"toggleExternalTripPayment(${t.id})\">${paymentStatusText}</button></span><span class=\"payment-status-print\">${paymentStatusText}</span>`\n      : '—';\n    return `<tr>\n      <td>${esc(t.date)}</td>\n      <td>${esc(d?.name||'')}</td>\n      <td>${esc(c?.name||'')}</td>\n      <td>${esc(t.from)}</td>\n      <td>${esc(t.to)}</td>\n      <td>${esc(t.delivery)}</td>\n      <td>${t.weight?esc(t.weight):'—'}</td>\n      <td>${t.image?`<img class=\"thumb\" src=\"${t.image}\" onclick=\"showImg(this.src)\">`:'—'}</td>\n      <td>${t.amount?esc(t.amount)+' ر.س':'—'}</td>\n      <td>${cashCollectionText}</td>\n      <td>${paymentCell}</td>\n      <td>\n        <div style=\"display:flex;gap:5px;flex-wrap:wrap;justify-content:center\">\n          <button class=\"btn gray\" type=\"button\" onclick=\"editTripAmount(${t.id})\">تعديل المبلغ</button>\n          <button class=\"btn red\" type=\"button\" onclick=\"deleteTrip(${t.id})\">حذف</button>\n        </div>\n      </td>\n    </tr>`;\n  }).join('') || '<tr><td colspan=\"12\" class=\"empty\">لا توجد مشاوير</td></tr>';\n}\n\nasync function addTrip() {\n  const customerId=Number($('customerSelect').value);\n  if(!customerId) return alert('اختر العميل');\n  const isExternal=detailType==='externalDriver';\n  const driverId=isExternal ? null : Number($('driverSelect').value);\n  if(!isExternal && !driverId) return alert('اختر السواق والعميل');\n  let image='';\n  const f=$('photo').files[0];\n  if(f) image=await new Promise(resolve=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.readAsDataURL(f);});\n  const trip={\n    id:nextId(db.trips), customerId, date:$('date').value,\n    from:$('from').value.trim(), to:$('to').value.trim(),\n    delivery:$('delivery').value.trim(), weight:$('weight').value,\n    amount:$('amount').value, image,\n    cashWithDriver: !isExternal && $('tripCashStatus').value==='driver_cash'\n  };\n  if(isExternal) {\n    trip.externalDriverId=detailId;\n    trip.externalPaymentStatus=$('externalTripPaymentStatus').value;\n  } else {\n    trip.driverId=driverId;\n  }\n  db.trips.push(trip);\n  archiveTripRoster(trip);\n  ['from','to','delivery','weight','amount'].forEach(id=>$(id).value='');\n  $('photo').value='';\n  if($('tripCashStatus')) $('tripCashStatus').value='account';\n  if($('externalTripPaymentStatus')) $('externalTripPaymentStatus').value='unpaid';\n  save();\n}\n\nfunction toggleExternalTripPayment(id) {\n  const t=db.trips.find(x=>x.id===id);\n  if(!t || !t.externalDriverId) return;\n  t.externalPaymentStatus = t.externalPaymentStatus==='paid' ? 'unpaid' : 'paid';\n  save();\n}\n\n\nfunction editTripAmount(id) {\n  const t=db.trips.find(x=>x.id===id);\n  if(!t) return;\n  const current = t.amount ?? '';\n  const value = prompt('اكتب مبلغ المشوار الجديد', current);\n  if(value===null) return;\n  const cleaned = String(value).trim();\n  if(cleaned==='') {\n    if(confirm('هل تريد مسح مبلغ هذا المشوار؟')) {\n      t.amount='';\n      save();\n    }\n    return;\n  }\n  const num = Number(cleaned);\n  if(!Number.isFinite(num) || num < 0) return alert('اكتب مبلغًا صحيحًا');\n  t.amount = String(num);\n  save();\n}\n\nfunction deleteTrip(id) {\n  if(confirm('حذف المشوار؟')) {\n    db.trips=db.trips.filter(t=>t.id!==id);\n    save();\n  }\n}\n\nfunction applyReportMonth() {\n  const m=$('reportMonth').value;\n  if(detailType==='driver' || detailType==='allDrivers' || detailType==='externalDriver') selectedDriverMonth=m;\n  if(detailType==='customer' || detailType==='allCustomers') selectedCustomerMonth=m;\n  renderDetail();\n}\n\nfunction printCurrentTable() {\n  const m=$('reportMonth').value;\n  if(detailType==='driver' || detailType==='allDrivers' || detailType==='externalDriver') selectedDriverMonth=m;\n  if(detailType==='customer' || detailType==='allCustomers') selectedCustomerMonth=m;\n  renderDetail();\n  window.print();\n}\n\nfunction printDriverForCustomer() {\n  if(detailType!=='driver') return;\n  selectedDriverMonth = $('reportMonth').value;\n  const customerId = Number($('driverCustomerReportSelect').value);\n  if(!customerId) return alert('اختر العميل أولاً');\n\n  const d = db.drivers.find(x=>x.id===detailId);\n  const c = db.customers.find(x=>x.id===customerId);\n  let trips = db.trips.filter(t=>t.driverId===detailId && t.customerId===customerId);\n  if(selectedDriverMonth) trips = trips.filter(t=>(t.date||'').slice(0,7)===selectedDriverMonth);\n  trips = trips.slice().sort((a,b)=>(a.date||'').localeCompare(b.date||''));\n\n  const totalAmount = trips.reduce((s,t)=>s+Number(t.amount||0),0);\n  const totalWeight = trips.reduce((s,t)=>s+Number(t.weight||0),0);\n\n  let html = `<div style=\"text-align:center\"><h2>كشف السائق للعميل</h2><div><strong>السائق:</strong> ${esc(d?.name||'')} ${d?.vehicle?'— السيارة: '+esc(d.vehicle):''}</div><div><strong>العميل:</strong> ${esc(c?.name||'')}</div><div><strong>الشهر الميلادي:</strong> ${esc(formatGregorianMonth(selectedDriverMonth))}</div></div>`;\n  html += `<div class=\"report-summary\"><div class=\"summary-pill\">عدد المشاوير: ${trips.length}</div><div class=\"summary-pill\">إجمالي الوزن: ${totalWeight.toLocaleString('ar-SA',{maximumFractionDigits:2})}</div><div class=\"summary-pill\">إجمالي المبلغ: ${totalAmount.toLocaleString('ar-SA',{maximumFractionDigits:2})} ر.س</div></div>`;\n\n  if(!trips.length) {\n    html += '<div class=\"empty\">لا توجد مشاوير لهذا السائق مع هذا العميل في الشهر المحدد</div>';\n  } else {\n    html += `<div class=\"customer-section\"><table><thead><tr><th>التاريخ</th><th>من</th><th>إلى</th><th>رقم السند</th><th>الوزن</th><th>المبلغ</th><th>التحصيل</th></tr></thead><tbody>`;\n    html += trips.map(t=>`<tr><td>${esc(t.date)}</td><td>${esc(t.from)}</td><td>${esc(t.to)}</td><td>${esc(t.delivery)}</td><td>${t.weight?esc(t.weight):'—'}</td><td>${t.amount?esc(t.amount)+' ر.س':'—'}</td><td>${t.cashWithDriver?'كاش مع السائق':'آجل / غير كاش'}</td></tr>`).join('');\n    html += `</tbody></table><div style=\"margin-top:8px;font-weight:700\">عدد المشاوير: ${trips.length} &nbsp; | &nbsp; إجمالي الوزن: ${totalWeight.toLocaleString('ar-SA',{maximumFractionDigits:2})} &nbsp; | &nbsp; إجمالي المبلغ: ${totalAmount.toLocaleString('ar-SA',{maximumFractionDigits:2})} ر.س</div></div>`;\n  }\n\n  $('groupedDriverReportContent').innerHTML = html;\n  document.body.classList.add('print-driver-customers');\n  window.print();\n  setTimeout(()=>document.body.classList.remove('print-driver-customers'),300);\n}\n\nfunction printDriverMonthlyFull() {\n  if(detailType!=='driver') return alert('افتح صفحة السائق أولاً');\n  const month = $('reportMonth').value || selectedDriverMonth || new Date().toISOString().slice(0,7);\n  selectedDriverMonth = month;\n  selectedExpenseMonth = month;\n  if($('reportMonth')) $('reportMonth').value = month;\n  if($('expenseMonth')) $('expenseMonth').value = month;\n\n  const d = db.drivers.find(x=>x.id===detailId);\n  let trips = db.trips.filter(t=>t.driverId===detailId && (t.date||'').slice(0,7)===month)\n    .slice().sort((a,b)=>(a.date||'').localeCompare(b.date||''));\n  let allExpenseEntries = db.expenses.filter(e=>e.driverId===detailId && (e.date||'').slice(0,7)===month)\n    .slice().sort((a,b)=>(a.date||'').localeCompare(b.date||''));\n  const advances = allExpenseEntries.filter(e=>(e.type||'').trim()==='سلفة');\n  const expenses = allExpenseEntries.filter(e=>(e.type||'').trim()!=='سلفة');\n\n  const tripTotal = trips.reduce((s,t)=>s+Number(t.amount||0),0);\n  const expenseTotal = expenses.reduce((s,e)=>s+Number(e.amount||0),0);\n  const advanceTotal = advances.reduce((s,e)=>s+Number(e.amount||0),0);\n  const deductionsTotal = expenseTotal + advanceTotal;\n  const cashTrips = trips.filter(t=>t.cashWithDriver);\n  const cashCollectedTotal = cashTrips.reduce((s,t)=>s+Number(t.amount||0),0);\n  const cashSpentEntries = allExpenseEntries.filter(e=>(e.paymentSource || (e.paidFromTripCash ? 'trip_cash' : 'other'))==='trip_cash');\n  const cashSpentTotal = cashSpentEntries.reduce((s,e)=>s+Number(e.amount||0),0);\n  const driverPaidEntries = allExpenseEntries.filter(e=>(e.paymentSource || (e.paidFromTripCash ? 'trip_cash' : 'other'))==='driver');\n  const driverPaidTotal = driverPaidEntries.reduce((s,e)=>s+Number(e.amount||0),0);\n  const cashBalance = cashCollectedTotal - cashSpentTotal;\n\n  let html = `<div style=\"text-align:center\">\n    <h2>كشف السائق الشهري - المشاوير والمصاريف والسلف والكاش</h2>\n    <div><strong>السائق:</strong> ${esc(d?.name||'')} ${d?.vehicle?'— السيارة / المقطورة: '+esc(d.vehicle):''}</div>\n    <div><strong>الشهر الميلادي:</strong> ${esc(formatGregorianMonth(month))}</div>\n  </div>`;\n\n  html += `<div class=\"report-summary\">\n    <div class=\"summary-pill\">عدد المشاوير: ${trips.length}</div>\n    <div class=\"summary-pill\">إجمالي المشاوير: ${tripTotal.toLocaleString('ar-SA',{maximumFractionDigits:2})} ر.س</div>\n    <div class=\"summary-pill\">إجمالي المصاريف: ${expenseTotal.toLocaleString('ar-SA',{maximumFractionDigits:2})} ر.س</div>\n    <div class=\"summary-pill\">إجمالي السلف: ${advanceTotal.toLocaleString('ar-SA',{maximumFractionDigits:2})} ر.س</div>\n    <div class=\"summary-pill\">إجمالي المصاريف + السلف: ${deductionsTotal.toLocaleString('ar-SA',{maximumFractionDigits:2})} ر.س</div>\n    <div class=\"summary-pill\">كاش استلمه السائق: ${cashCollectedTotal.toLocaleString('ar-SA',{maximumFractionDigits:2})} ر.س</div>\n    <div class=\"summary-pill\">صُرف من الكاش: ${cashSpentTotal.toLocaleString('ar-SA',{maximumFractionDigits:2})} ر.س</div>\n    <div class=\"summary-pill\">دفعه السائق من ماله: ${driverPaidTotal.toLocaleString('ar-SA',{maximumFractionDigits:2})} ر.س</div>\n    <div class=\"summary-pill\">المتبقي مع السائق: ${cashBalance.toLocaleString('ar-SA',{maximumFractionDigits:2})} ر.س</div>\n  </div>`;\n\n  html += `<div class=\"report-section\"><h3>مشاوير الشهر</h3>`;\n  if(!trips.length) {\n    html += '<div class=\"empty\">لا توجد مشاوير لهذا السائق في الشهر المحدد</div>';\n  } else {\n    html += `<table><thead><tr><th>التاريخ</th><th>العميل</th><th>من</th><th>إلى</th><th>رقم السند</th><th>الوزن</th><th>المبلغ</th><th>التحصيل</th></tr></thead><tbody>`;\n    html += trips.map(t=>{\n      const c=db.customers.find(x=>x.id===t.customerId);\n      return `<tr><td>${esc(t.date)}</td><td>${esc(c?.name||'')}</td><td>${esc(t.from)}</td><td>${esc(t.to)}</td><td>${esc(t.delivery)}</td><td>${t.weight?esc(t.weight):'—'}</td><td>${t.amount?esc(t.amount)+' ر.س':'—'}</td><td>${t.cashWithDriver?'كاش مع السائق':'آجل / غير كاش'}</td></tr>`;\n    }).join('');\n    html += `</tbody></table><div style=\"margin-top:8px;font-weight:700\">إجمالي مشاوير الشهر: ${tripTotal.toLocaleString('ar-SA',{maximumFractionDigits:2})} ر.س</div>`;\n  }\n  html += `</div>`;\n\n  html += `<div class=\"report-section\"><h3>مصاريف الشهر</h3>`;\n  if(!expenses.length) {\n    html += '<div class=\"empty\">لا توجد مصاريف لهذا السائق في الشهر المحدد</div>';\n  } else {\n    html += `<table><thead><tr><th>التاريخ</th><th>نوع المصروف</th><th>المبلغ</th><th>مصدر الدفع</th><th>ملاحظة</th></tr></thead><tbody>`;\n    html += expenses.map(e=>`<tr><td>${esc(e.date)}</td><td>${esc(e.type)}</td><td>${Number(e.amount||0).toLocaleString('ar-SA',{maximumFractionDigits:2})} ر.س</td><td>${expensePaymentSource(e)}</td><td>${esc(e.note||'')}</td></tr>`).join('');\n    html += `</tbody></table><div style=\"margin-top:8px;font-weight:700\">إجمالي مصاريف الشهر: ${expenseTotal.toLocaleString('ar-SA',{maximumFractionDigits:2})} ر.س</div>`;\n  }\n  html += `</div>`;\n\n  html += `<div class=\"report-section\"><h3>سلف الشهر</h3>`;\n  if(!advances.length) {\n    html += '<div class=\"empty\">لا توجد سلف لهذا السائق في الشهر المحدد</div>';\n  } else {\n    html += `<table><thead><tr><th>التاريخ</th><th>المبلغ</th><th>مصدر الدفع</th><th>ملاحظة</th></tr></thead><tbody>`;\n    html += advances.map(e=>`<tr><td>${esc(e.date)}</td><td>${Number(e.amount||0).toLocaleString('ar-SA',{maximumFractionDigits:2})} ر.س</td><td>${expensePaymentSource(e)}</td><td>${esc(e.note||'')}</td></tr>`).join('');\n    html += `</tbody></table><div style=\"margin-top:8px;font-weight:700\">إجمالي سلف الشهر: ${advanceTotal.toLocaleString('ar-SA',{maximumFractionDigits:2})} ر.س</div>`;\n  }\n  html += `</div>`;\n\n  html += `<div class=\"report-section\"><h3>حركة كاش المشاوير مع السائق</h3>`;\n  html += `<div class=\"report-summary\">\n    <div class=\"summary-pill\">الكاش المستلم: ${cashCollectedTotal.toLocaleString('ar-SA',{maximumFractionDigits:2})} ر.س</div>\n    <div class=\"summary-pill\">المصروف من الكاش: ${cashSpentTotal.toLocaleString('ar-SA',{maximumFractionDigits:2})} ر.س</div>\n    <div class=\"summary-pill\">المتبقي مع السائق: ${cashBalance.toLocaleString('ar-SA',{maximumFractionDigits:2})} ر.س</div>\n  </div>`;\n  if(cashTrips.length) {\n    html += `<h3 style=\"font-size:15px\">المشاوير الكاش</h3><table><thead><tr><th>التاريخ</th><th>العميل</th><th>رقم السند</th><th>المبلغ</th></tr></thead><tbody>`;\n    html += cashTrips.map(t=>{ const c=db.customers.find(x=>x.id===t.customerId); return `<tr><td>${esc(t.date)}</td><td>${esc(c?.name||'')}</td><td>${esc(t.delivery||'')}</td><td>${Number(t.amount||0).toLocaleString('ar-SA',{maximumFractionDigits:2})} ر.س</td></tr>`; }).join('');\n    html += `</tbody></table>`;\n  } else {\n    html += '<div class=\"empty\">لا توجد مشاوير كاش مع السائق في الشهر المحدد</div>';\n  }\n  if(cashSpentEntries.length) {\n    html += `<h3 style=\"font-size:15px\">المبالغ المصروفة من كاش المشاوير</h3><table><thead><tr><th>التاريخ</th><th>النوع</th><th>المبلغ</th><th>ملاحظة</th></tr></thead><tbody>`;\n    html += cashSpentEntries.map(e=>`<tr><td>${esc(e.date)}</td><td>${esc(e.type)}</td><td>${Number(e.amount||0).toLocaleString('ar-SA',{maximumFractionDigits:2})} ر.س</td><td>${esc(e.note||'')}</td></tr>`).join('');\n    html += `</tbody></table>`;\n  }\n  html += `</div>`;\n\n  $('monthlyDriverReportContent').innerHTML = html;\n  document.body.classList.add('print-driver-monthly');\n  window.print();\n  setTimeout(()=>document.body.classList.remove('print-driver-monthly'),300);\n}\n\nfunction addExternalDriver() {\n  const name=$('externalDriverName').value.trim();\n  if(!name) return alert('اكتب اسم السائق الخارجي');\n  const vehicle=$('externalDriverVehicle').value.trim();\n  db.externalDrivers.push({id:nextId(db.externalDrivers),name,vehicle});\n  $('externalDriverName').value='';\n  $('externalDriverVehicle').value='';\n  save();\n  renderHome();\n}\n\nfunction applyExpenseMonth() {\n  if(detailType!=='driver') return;\n  selectedExpenseMonth = $('expenseMonth').value;\n  renderDetail();\n}\n\nfunction printExpenses() {\n  if(detailType!=='driver') return;\n  selectedExpenseMonth = $('expenseMonth').value;\n  renderDetail();\n  document.body.classList.add('print-expenses');\n  window.print();\n  setTimeout(()=>document.body.classList.remove('print-expenses'), 300);\n}\n\nasync function addExpense() {\n  if(detailType!=='driver') return;\n  const amount=$('expenseAmount').value;\n  if(!amount) return alert('اكتب مبلغ المصروف');\n\n  let image='';\n  const f=$('expensePhoto').files[0];\n  if(f) image = await new Promise(resolve=>{\n    const r=new FileReader();\n    r.onload=()=>resolve(r.result);\n    r.readAsDataURL(f);\n  });\n\n  db.expenses.push({\n    id:nextId(db.expenses),\n    driverId:detailId,\n    date:$('expenseDate').value,\n    type:$('expenseType').value,\n    amount:amount,\n    paymentSource:$('expenseCashSource').value,\n    paidFromTripCash:$('expenseCashSource').value==='trip_cash',\n    note:$('expenseNote').value.trim(),\n    image:image\n  });\n\n  $('expenseAmount').value='';\n  if($('expenseCashSource')) $('expenseCashSource').value='other';\n  $('expenseNote').value='';\n  $('expensePhoto').value='';\n  save();\n}\n\nfunction deleteExpense(id) {\n  if(confirm('حذف المصروف؟')) {\n    db.expenses=db.expenses.filter(e=>e.id!==id);\n    save();\n  }\n}\n\nfunction showImg(src) {\n  $('big').src=src;\n  $('modal').classList.add('on');\n}\n\nrenderHome();\n</script>\n</body>\n</html>";

const PRINT_BRIDGE = `
(function() {
  try {
    window.print = function() {
      try {
        window.ReactNativeWebView.postMessage(JSON.stringify({
          type: 'print',
          html: document.documentElement.outerHTML
        }));
      } catch (e) {}
    };
  } catch (e) {}
})();
true;
`;

export default function App() {
  const handleMessage = async (event) => {
    try {
      const message = JSON.parse(event.nativeEvent.data || '{}');
      if (message.type === 'print' && message.html) {
        await Print.printAsync({ html: message.html });
      }
    } catch (error) {
      Alert.alert('مدد العاصمة', 'تعذر فتح الطباعة.');
    }
  };

  return (
    <SafeAreaView style={styles.container}>
      <WebView
        style={styles.webview}
        source={{ html: APP_HTML, baseUrl: 'https://madad.local/' }}
        originWhitelist={['*']}
        javaScriptEnabled
        domStorageEnabled
        databaseEnabled
        allowFileAccess
        allowContentAccess
        setSupportMultipleWindows={false}
        injectedJavaScript={PRINT_BRIDGE}
        onMessage={handleMessage}
        mixedContentMode="compatibility"
      />
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, backgroundColor: '#ffffff' },
  webview: { flex: 1, backgroundColor: '#ffffff' },
});
